func Run(ctx *context.Context, dir string, command, env []string, output bool) error {
	if len(command) == 0 {
		log.Warn("no command to run, skipping")
		return nil
	}

	/* #nosec */
	cmd := exec.CommandContext(ctx, command[0], command[1:]...)

